export type SparePart = {
  name: string;
  article: string;
  category: string;
  description: string;
  image: string;
  sourceUrl: string;
  slug?: string;
};

export type SparePartsBrand = {
  slug: string;
  name: string;
  alias?: string;
  logo?: string;
  parts: SparePart[];
};

type SourceRow = [string, string, string, string, string, string?];
const parts = (brand: string, rows: SourceRow[]): SparePart[] => rows.map(([name, article, category, image, sourceUrl, slug]) => ({
  name, article, category, image, sourceUrl, slug,
  description: `Запчасть для котлов ${brand}. Совместимость уточняйте по модели и серийному номеру.`,
}));

